{
  "name": "opencode2-goal-plugin",
  "version": "1.0.9",
  "description": "Persistent session goals for OpenCode V2",
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./source": "./index.ts"
  },
  "files": ["dist", "index.ts", "src"],
  "scripts": {
    "lint": "oxlint .",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "build": "bun build index.ts --outdir dist --target bun --format esm --external @opencode/plugin",
    "prepack": "bun run build"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.21"
  },
  "devDependencies": {
    "@oxlint/plugins": "1.86.0",
    "@types/bun": "1.4.2",
    "oxlint": "1.86.0",
    "typescript": "7.0.2"
  },
  "engines": {
    "bun": ">=1.2.0"
  },
  "license": "MIT",
  "author": {
    "name": "Omkar Chandorkar",
    "email": "gotenksIN@aospa.co"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/gotenksIN/opencode2-goal-plugin.git"
  },
  "homepage": "https://github.com/gotenksIN/opencode2-goal-plugin"
}
